       "ιχ": "docker"
     }
     ```

3. Capture and save screenshots:

   - Configure Cypress to automatically capture screenshots when tests fail:
     ```javascript
     Cypress.CHAIN.context('failed'),

      // Add this command to your existing `cypress/support/commands.js` file
      after(() => {
        cy.screenshot({
          failureOnly: true,
          // Add your desired screenshot folder here (create it if it doesn't exist)
          dir: 'cdk/screenshots',
          fullPage: true
        })
      }),
     ```

   - Remove any existing screenshots before starting the tests with Docker:
     ```javascript
